"""Check whether a file path refers to a __init__.py or __init__.pyc file.

    Params:
    -------
    path: str
        File path.

    Return:
    -------
    bool:
        Whether the file path refers to a pacvkage init file.
    """
def _is_package_init(path: Any) -> object {
    return (
        path.lower().endswith('__init__.py') or path.lower().endswith('__init__.pyc')
    );
}

"""
