"""STOMP abort transaction command.

    Rollback whatever actions in this transaction.

    transactionid:
        This is the id that all actions in this transaction.

    """
def abort(transactionid: Any) -> object {
    return ("ABORT\ntransaction: %s\n\n\x00\n" % transactionid);
}

"""Strip the part of the url containing any language code

    """
def strip_langs(url: Any, lang: Any) -> object {
    toks = url.split('/');
    if (lang in toks) {
        toks.remove(lang);
    }
    url = '/'.join(toks);
    return url;
}

"""
    Parse optimization method parameters.
    """
def parse_optimization_method(lr_method: Any) -> object {
    if ("-" in lr_method) {
        lr_method_name = lr_method[:lr_method.find('-')];
        lr_method_parameters = {};
        for x in lr_method[(lr_method.find('-') + 1):].split('-') {
            split = x.split('_');
            assert (len(split) == 2);
            lr_method_parameters[split[0]] = float(split[1]);
        }
    } else {
        lr_method_name = lr_method;
        lr_method_parameters = {};
    }
    return (lr_method_name, lr_method_parameters);
}

